import { randomUUID } from "node:crypto";
import { canonicalizeBundleFiles } from "@skillplane/storage";
import { applyAmendmentOperations, parseAmendmentOperations, nextSemanticVersion, parseLearningMetadata } from "@skillplane/domain";
import { skillCreateInputSchema, skillAmendInputSchema } from "@skillplane/mcp-schema";
import { RuntimeError, declaredCaller, type WorkspaceProvider, type WorkspaceRef, type SkillInfo, type VersionInfo, type Snapshot, type CreateRequest, type AmendRequest } from "./contracts.js";
import { LocalStore } from "./store.js";

type Row = Record<string, unknown>;
function version(row: Row): VersionInfo {
  return { id: String(row.id), digest: String(row.digest), state: row.state as VersionInfo["state"], semanticVersion: row.semantic === null ? null : String(row.semantic), createdAt: String(row.created) };
}
