    this.workspace = { provider: "local", id: workspaceId };
  }
  static create(store: LocalStore, name: string): LocalWorkspaceProvider {
    if (!name.trim() || name.length > 120) throw new RuntimeError("WORKSPACE_NAME_INVALID");
    const id = store.transaction(() => {
      const row = store.db.prepare("SELECT id FROM workspace WHERE name=?").get(name);
      if (row) return String(row.id);
      const id = randomUUID(); store.db.prepare("INSERT INTO workspace VALUES(?,?)").run(id, name); return id;
    });
    return new LocalWorkspaceProvider(store, id);
  }
  async list(): Promise<SkillInfo[]> {
    return this.store.db.prepare("SELECT id,slug,name,description FROM skill WHERE workspace=? ORDER BY slug").all(this.workspace.id) as unknown as SkillInfo[];
  }
  private skill(id: string): Row {
    const row = this.store.db.prepare("SELECT * FROM skill WHERE id=? AND workspace=?").get(id, this.workspace.id);
    if (!row) throw new RuntimeError("SKILL_NOT_FOUND"); return row;
  }
  async versions(skillId: string): Promise<VersionInfo[]> {
    this.skill(skillId);
    return this.store.db.prepare("SELECT * FROM version WHERE skill=? ORDER BY created DESC,id").all(skillId).map(version);
  }
  async retrieve(skillId: string, versionId?: string): Promise<Snapshot> {
    const skill = this.skill(skillId);
    const row = this.store.db.prepare("SELECT * FROM version WHERE skill=? AND id=?").get(skillId, versionId ?? String(skill.current));
    if (!row) throw new RuntimeError("VERSION_UNAVAILABLE");
    return { workspace: this.workspace, skill: { id: skillId, slug: String(skill.slug), name: String(skill.name), description: String(skill.description) }, version: version(row), bundle: await this.store.bundle(String(row.digest)) };
  }
  async create(request: CreateRequest): Promise<{ skillId: string; versionId: string }> {
    const input = skillCreateInputSchema.parse({ ...request, workspace: { id: this.workspace.id }, caller: declaredCaller() });
