    const replay = this.store.replay<{ skillId: string; versionId: string }>(key, request); if (replay) return replay;
    const files = new Map<string, Uint8Array>([["SKILL.md", Buffer.from(input.instructions)]]);
    for (const asset of input.assets) files.set(asset.path, asset.content !== undefined ? Buffer.from(asset.content) : Buffer.from(asset.contentBase64!, "base64"));
    const bundle = await canonicalizeBundleFiles({ skill: { formatVersion: 1, name: input.name, slug: input.slug, description: input.description, tags: input.tags, entrypoint: "SKILL.md" }, files });
    this.store.putBundle(bundle);
    return this.store.transaction(() => {
      const replay = this.store.replay<{ skillId: string; versionId: string }>(key, request); if (replay) return replay;
      if (this.store.db.prepare("SELECT id FROM skill WHERE workspace=? AND slug=?").get(this.workspace.id, input.slug)) throw new RuntimeError("SKILL_SLUG_CONFLICT");
      const result = { skillId: `skill:${randomUUID()}`, versionId: `skill-version:${randomUUID()}` };
      this.store.db.prepare("INSERT INTO skill VALUES(?,?,?,?,?,NULL)").run(result.skillId, this.workspace.id, input.slug, input.name, input.description);
