export interface SecretStore { get(key: string): Promise<string>; set(key: string, value: string): Promise<void>; delete(key: string): Promise<void> }
function command(program: string, args: string[], input?: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = spawn(program, args, { stdio: ["pipe", "pipe", "pipe"] });
    let output = "";
    child.stdout.on("data", chunk => { output += String(chunk); });
    child.on("error", () => reject(new RuntimeError("SECRET_SERVICE_UNAVAILABLE")));
